describe('Filter Tag Removal', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should remove an individual filter tag by clicking the x icon', () => {
    // Apply multiple filters
    cy.get('[data-testid="filter-category-tag"]').click();
    cy.get('[data-testid="filter-price-tag"]').click();
    cy.get('[data-testid="filter-status-tag"]').click();

    // Verify all tags are visible
    cy.get('[data-testid="filter-tag"]').should('have.length', 3);
    cy.get('[data-testid="filter-tag"]').first().should('contain', 'Category');
    cy.get('[data-testid="filter-tag"]').eq(1).should('contain', 'Price');
    cy.get('[data-testid="filter-tag"]').eq(2).should('contain', 'Status');

    // Click the remove icon on the first tag
    cy.get('[data-testid="filter-tag"]').first().find('[data-testid="remove-tag-icon"]').click();

    // Verify the first tag is removed
    cy.get('[data-testid="filter-tag"]').should('have.length', 2);
    cy.get('[data-testid="filter-tag"]').first().should('contain', 'Price');
    cy.get('[data-testid="filter-tag"]').eq(1).should('contain', 'Status');

    // Verify the search results update
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-results"]').should('contain', 'Showing results');
  });

  it('should handle removing the last filter tag and clear all filters', () => {
    // Apply multiple filters
    cy.get('[data-testid="filter-category-tag"]').click();
    cy.get('[data-testid="filter-price-tag"]').click();
    cy.get('[data-testid="filter-status-tag"]').click();

    // Remove the first tag
    cy.get('[data-testid="filter-tag"]').first().find('[data-testid="remove-tag-icon"]').click();

    // Remove the second tag
    cy.get('[data-testid="filter-tag"]').first().find('[data-testid="remove-tag-icon"]').click();

    // Verify only one tag remains
    cy.get('[data-testid="filter-tag"]').should('have.length', 1);
    cy.get('[data-testid="filter-tag"]').first().should('contain', 'Status');

    // Remove the last tag
    cy.get('[data-testid="filter-tag"]').first().find('[data-testid="remove-tag-icon"]').click();

    // Verify all tags are removed
    cy.get('[data-testid="filter-tag"]').should('not.exist');

    // Verify search results are reset to default
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-results"]').should('contain', 'Showing all results');
    cy.get('[data-testid="filter-reset-button"]').should('be.visible');
  });
});
